#include <bit>
#include <bitset>
#include <iostream>

int main() {
    using bin = std::bitset<8>;
    for (unsigned x{}; x != 012; ++x)
        std::cout << "bit_floor( " << bin(x) << " ) = " << bin(std::bit_floor(x))
                  << '\n';
}
